import { MakeLogicType, actions, kea, path, reducers } from 'kea'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface visionDockPreferenceLogicValues {
    preferredSummarizerId: string | null
    summaryDockAutoExpand: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface visionDockPreferenceLogicActions {
    setPreferredSummarizerId: (scannerId: string | null) => {
        scannerId: string | null
    }
    setSummaryDockAutoExpand: (autoExpand: boolean) => {
        autoExpand: boolean
    }
}

export type visionDockPreferenceLogicType = MakeLogicType<
    visionDockPreferenceLogicValues,
    visionDockPreferenceLogicActions
>

/**
 * How the summary dock behaves, across recordings.
 *
 * Propless and persisted on purpose. `observationsDockLogic` is keyed by session, so a preference
 * kept there would reset on every recording the user opens: it would re-expand a dock they just
 * collapsed, and forget the summarizer they just picked.
 */
export const visionDockPreferenceLogic = kea<visionDockPreferenceLogicType>([
    path(['products', 'replay_vision', 'frontend', 'logics', 'visionDockPreferenceLogic']),

    actions({
        setSummaryDockAutoExpand: (autoExpand: boolean) => ({ autoExpand }),
        setPreferredSummarizerId: (scannerId: string | null) => ({ scannerId }),
    }),

    reducers({
        summaryDockAutoExpand: [
            true,
            { persist: true },
            {
                setSummaryDockAutoExpand: (_: boolean, { autoExpand }: { autoExpand: boolean }) => autoExpand,
            },
        ],
        // Holds a scanner id, BUILT_IN_SUMMARIZER, or null for "never chose". Resolved against the
        // team's current scanner list by `resolveSummarizer`, so a stale id falls back on its own.
        preferredSummarizerId: [
            null as string | null,
            { persist: true },
            {
                setPreferredSummarizerId: (_: string | null, { scannerId }: { scannerId: string | null }) => scannerId,
            },
        ],
    }),
])
